import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long n = Long.parseLong(next());
        String[] words = new String[(int) n];
        for (int i = 0; i < words.length; i++) words[i] = next();

        final long MOD = 1000000007L;
        HashSet<String> dictionary = new HashSet<>();
        int longest = 0;
        for (int k = 0; k < n; k++) {
            dictionary.add(words[k]);
            longest = Math.max(longest, words[k].length());
        }
        int m = s.length();
        long[] ways = new long[m + 1];
        ways[0] = 1;
        for (int i = 0; i < m; i++) {
            if (ways[i] == 0) continue;
            for (int L = 1; L <= longest && i + L <= m; L++) {
                if (dictionary.contains(s.substring(i, i + L))) ways[i + L] = (ways[i + L] + ways[i]) % MOD;
            }
        }
        System.out.println(ways[m]);
    }
}
